    public async Task<string> CreateWebApplicationClientAsync(
        string realm, 
        string clientId, 
        string clientName, 
        string[] redirectUris)
    {
        var provider = _keycloakService.GetAdminWithBasicAuth("admin", "admin-password");
        
        try
        {
            var newClient = new Client
            {
                ClientId = clientId,
                Name = clientName,
                Enabled = true,
