    var role = await provider.Roles.GetRoleByNameAsync(realm, clientId, roleName);
    
    // Remove role from user
    var success = await provider.Roles.RemoveRoleFromUserAsync(realm, clientId, userId, new[] { role });
    return success;
}

public async Task<IEnumerable<Role>> GetUserRolesAsync(string realm, string clientId, string userId)
{
    var provider = await GetAdminProviderAsync();
    
    // Get all roles assigned to a user
    var roles = await provider.Roles.GetUsersWithRoleNameAsync(realm, clientId, roleName);
    return roles;
}
```

# Complete User Management Service

This comprehensive example demonstrates how to build a complete user management service that handles all aspects of user lifecycle management.

``` csharp
public class KeycloakUserService
{
    private readonly IKeycloakAdminService _keycloakService;
    private readonly string _realm;
    private readonly ILogger<KeycloakUserService> _logger;

    public KeycloakUserService(
        IKeycloakAdminService keycloakService, 
        string realm,
        ILogger<KeycloakUserService> logger)
    {
        _keycloakService = keycloakService;
        _realm = realm;
        _logger = logger;
    }

    public async Task<string> CreateUserWithRoleAsync(
        string username, 
        string email, 
        string firstName, 
        string lastName, 
        string clientId, 
        string roleName)
    {
        var provider = _keycloakService.GetAdminWithBasicAuth("admin", "admin-password");
        
        try
        {
            // 1. Create user
            var newUser = new User
            {
                UserName = username,
                Email = email,
                FirstName = firstName,
                LastName = lastName,
                Enabled = true,
                EmailVerified = true
            };

            var userId = await provider.Users.CreateAndRetrieveUserIdAsync(_realm, newUser);
            
            if (string.IsNullOrEmpty(userId))
            {
                throw new InvalidOperationException("Failed to create user");
            }

            // 2. Assign role to user
            var role = await provider.Roles.GetRoleByNameAsync(_realm, clientId, roleName);
            if (role != null)
            {
                await provider.Roles.AddRoleToUserAsync(_realm, clientId, userId, new[] { role });
            }

            _logger.LogInformation("Successfully created user {Username} with role {RoleName}", username, roleName);
            return userId;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to create user with role: {Message}", ex.Message);
            throw new InvalidOperationException($"Failed to create user with role: {ex.Message}", ex);
        }
    }

    public async Task<bool> UpdateUserProfileAsync(string userId, string firstName, string lastName, string email)
    {
        var provider = _keycloakService.GetAdminWithBasicAuth("admin", "admin-password");
        
        try
        {
            // Get existing user
            var existingUser = await provider.Users.GetUserAsync(_realm, userId);
            
            // Update properties
            existingUser.FirstName = firstName;
            existingUser.LastName = lastName;
            existingUser.Email = email;
            
            // Save changes
            var success = await provider.Users.UpdateUserAsync(_realm, userId, existingUser);
            
            if (success)
            {
                _logger.LogInformation("Successfully updated profile for user {UserId}", userId);
            }
            
            return success;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to update user profile: {Message}", ex.Message);
            throw new InvalidOperationException($"Failed to update user profile: {ex.Message}", ex);
        }
    }

    public async Task<bool> DeactivateUserAsync(string userId)
    {
        var provider = _keycloakService.GetAdminWithBasicAuth("admin", "admin-password");
        
        try
        {
            // Get existing user
            var existingUser = await provider.Users.GetUserAsync(_realm, userId);
            
            // Disable user
            existingUser.Enabled = false;
            
            // Save changes
            var success = await provider.Users.UpdateUserAsync(_realm, userId, existingUser);
            
            if (success)
            {
                _logger.LogInformation("Successfully deactivated user {UserId}", userId);
            }
            
            return success;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to deactivate user: {Message}", ex.Message);
            throw new InvalidOperationException($"Failed to deactivate user: {ex.Message}", ex);
        }
    }

    public async Task<bool> ReactivateUserAsync(string userId)
    {
        var provider = _keycloakService.GetAdminWithBasicAuth("admin", "admin-password");
        
        try
        {
            var existingUser = await provider.Users.GetUserAsync(_realm, userId);
            existingUser.Enabled = true;
            
            var success = await provider.Users.UpdateUserAsync(_realm, userId, existingUser);
            
            if (success)
            {
                _logger.LogInformation("Successfully reactivated user {UserId}", userId);
            }
            
            return success;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to reactivate user: {Message}", ex.Message);
            throw new InvalidOperationException($"Failed to reactivate user: {ex.Message}", ex);
        }
    }
}
```

# Introduction

The `Six.KeycloakAdmin` library provides seamless integration with **.NET Aspire**, Microsoft's cloud-ready stack for building observable, production-ready distributed applications. This integration enables automatic service discovery, simplified configuration, and enhanced observability for Keycloak administrative operations in containerized and cloud environments.

By leveraging Aspire's service discovery capabilities, **developers can eliminate hardcoded URLs and connection strings,** making applications more portable and environment-agnostic. 

# Basic Setup

## 1. AppHost Configuration

Create or update your Aspire AppHost project to include Keycloak resource and reference your project (in this 
example, `MyApi`:

``` csharp
// Program.cs in your AppHost project
var builder = DistributedApplication.CreateBuilder(args);

// Add Keycloak as a managed resource
var keycloak = builder.AddKeycloak("keycloak", 8080)
    .WithDataVolume()
    .WithRealmImport("realm-export.json"); // Optional: import realm configuration

// Add your API project that will use KeycloakAdmin
builder.AddProject<Projects.MyApi>("myapi")
    .WithReference(keycloak);

builder.Build().Run();
```

## 2. Service Registration with Aspire Integration

In your API or service project, just register the `KeycloakAdmin` and set the name of the Keycloak resource as you 
did define it in the `AppHost` project (in this example, `keycloak`):

``` csharp
// Program.cs in your API project
var builder = WebApplication.CreateBuilder(args);

// Register KeycloakAdmin with Aspire service discovery
builder.Services.AddKeycloakAdmin("keycloak", options =>
{
    options.AdminClientId = "admin-cli";
    options.HttpTimeout = TimeSpan.FromSeconds(30);
    // BaseUrl is automatically set to "http+https://keycloak" for service discovery
});

var app = builder.Build();
```

## 3. Using the Admin Client

Once configured, inject and use the Keycloak admin services as usual:

``` csharp
// In your controller or service
public class UserController : ControllerBase
{
    private readonly IKeycloakAdminService _keycloakAdminService;

    public UserController(IKeycloakAdminService keycloakAdminService)
    {
        _keycloakAdminService = keycloakAdminService;
    }

    [HttpGet("users")]
    public async Task<IActionResult> GetUsers()
    {
        // Get admin provider (automatically uses service discovery)
        // Note: For production, consider using secure secret services like Azure Key Vault instead of environment variables
        var adminProvider = _keycloakAdminService.GetAdminWithBasicAuth(
            Environment.GetEnvironmentVariable("KEYCLOAK_ADMIN_USERNAME") ?? "admin",
            Environment.GetEnvironmentVariable("KEYCLOAK_ADMIN_PASSWORD") ?? "admin");
        
        var users = await adminProvider.Users.GetUsersAsync("master");
        return Ok(users);
    }
}
```

